import { templateVariableProjectionToValue } from './template-variable.model';
import { ComponentFixture, TestBed } from '@angular/core/testing';
import {
  InteractionMocks,
  RepositoryMock,
  allow,
  configureFeatureTesting,
  createWithoutTemplate,
  internals,
  mockRepository,
  mockTick,
  moduleCompiles,
} from 'app/shared/testing/feature-testing';

describe('templateVariableProjectionToValue', () => {
  const value = {
    uid: 'value-uid',
    code: 'value-code',
    tenant: { $ref: 'ref-tenant' },
    type: 'value-type',
    value: 'value-value',
    enabled: 'value-enabled',
    version: 'value-version',
  } as any;

  it('returns null without projection', () => {
    expect(templateVariableProjectionToValue(null)).toBeNull();
    expect(templateVariableProjectionToValue(undefined)).toBeNull();
  });

  it('keeps a plain value', () => {
    expect(templateVariableProjectionToValue(value)).toEqual(value);
  });

  it('reduces the projected references to their key', () => {
    const projection = {
      uid: 'value-uid',
      code: 'value-code',
      tenant: () => ({ uid: 'ref-tenant' }),
      type: 'value-type',
      value: 'value-value',
      enabled: 'value-enabled',
      version: 'value-version',
    } as any;
    expect(templateVariableProjectionToValue(projection)).toEqual(value);
  });
});
